// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address potentialOwner) public {
        vm.assume(potentialOwner != address(0));

        vm.prank(address(0));
        c.transferOwnership(potentialOwner);

        address before = c.owner();
        assertTrue(before == potentialOwner);

        vm.prank(potentialOwner);
        c.owned();

        assertTrue(c.owner() == before);
    }
}
